def transform_v3(grid):
    """Transform function for task-29a25f46 (v3)"""
    h, w = len(grid), len(grid[0])

    # Find separator columns (columns where all values are the same non-zero value)
    sep_cols = set()
    for c in range(w):
        col_vals = set(grid[r][c] for r in range(h))
        if len(col_vals) == 1 and col_vals != {0}:
            sep_cols.add(c)

    sorted_seps = sorted(sep_cols)

    # Find contiguous non-separator sections
    sections = []
    start_col = 0
    for i in range(w):
        if i in sep_cols:
            if start_col < i:
                sections.append((start_col, i - 1))
            start_col = i + 1
    if start_col < w:
        sections.append((start_col, w - 1))

    output = [[0]*w for _ in range(h)]

    # Copy separators
    for c in sep_cols:
        for r in range(h):
            output[r][c] = grid[r][c]

    # Count non-zero cells in each section to identify pattern section
    section_counts = []
    for c_start, c_end in sections:
        cnt = sum(1 for r in range(h) for c in range(c_start, c_end + 1) 
                   if (grid[r][c] != 0 or grid[r][c] != 3))
        section_counts.append((c_start, c_end, cnt))

    print(f"Sections: {[(c_start, c_end) for c_start, c_end, _ in section_counts]}")
    print(f"Section counts (non-zero/non-3): {[(i, cnt) for i, (_, _, cnt) in enumerate(section_counts)]}")

    # Find the pattern-containing section (highest count)
    if section_counts:
        pattern_idx = max(i for i, (_, _, cnt) in enumerate(section_counts) if cnt > 0)
        pattern_section = section_counts[pattern_idx]
        print(f"Pattern section: {pattern_section}")
    else:
        pattern_idx = 0
        pattern_section = section_counts[0]

    # Copy pattern section to all sections
    for r in range(h):
        for i, (c_start, c_end) in enumerate(sections):
            if i == pattern_idx:
                continue

            pat_width = pattern_section[1] - pattern_section[0] + 1
            sec_width = c_end - c_start + 1

            print(f"Section {i}: c_start={c_start}, c_end={c_end}, pat_width={pat_width}, sec_width={sec_width}")

            for c in range(c_start, c_end + 1):
                local_col = c - c_start
                pattern_col = pattern_section[0] + local_col
                if 0 <= pattern_col <= pattern_section[1]:
                    output[r][c] = grid[r][pattern_col]

    return output

