def transform_final(grid):
    """Final transform for task-29a25f46

    Rule: Copy the pattern-containing section to all other sections.
    Background is detected as the most common value in the first section.
    """
    h, w = len(grid), len(grid[0])

    # Find separator columns
    sep_cols = set()
    for c in range(w):
        col_vals = set(grid[r][c] for r in range(h))
        if len(col_vals) == 1 and col_vals != {0}:
            sep_cols.add(c)

    sorted_seps = sorted(sep_cols)

    # Find contiguous non-separator sections
    sections = []
    start_col = 0
    for i in range(w):
        if i in sep_cols:
            if start_col < i:
                sections.append((start_col, i - 1))
            start_col = i + 1
    if start_col < w:
        sections.append((start_col, w - 1))

    output = [[0]*w for _ in range(h)]

    # Copy separators
    for c in sep_cols:
        for r in range(h):
            output[r][c] = grid[r][c]

    # Initialize output sections with input sections
    for r in range(h):
        for i, (c_start, c_end) in enumerate(sections):
            for c in range(c_start, c_end + 1):
                output[r][c] = grid[r][c]

    # Find background (most common value in first section)
    first_c_start, first_c_end = sections[0]
    first_section_vals = [grid[r][c] for r in range(h) for c in range(first_c_start, first_c_end + 1)]
    from collections import Counter
    bg = Counter(first_section_vals).most_common(1)[0][0]

    # Find pattern section (most non-background values)
    best_section = None
    best_count = -1

    for i, (c_start, c_end) in enumerate(sections):
        cnt = sum(1 for c in range(c_start, c_end + 1) for r in range(h) 
                   if grid[r][c] != bg and grid[r][c] not in sep_cols)
        if cnt > best_count:
            best_count = cnt
            best_section = i

    if best_section is None:
        best_section = 0

    print(f"Background: {bg}, Pattern section: {best_section}")

    pattern_section = sections[best_section]

    # Copy pattern to all sections
    for r in range(h):
        for i, (c_start, c_end) in enumerate(sections):
            if i == best_section:
                continue

            for c in range(c_start, c_end + 1):
                local_col = c - c_start
                pattern_col = pattern_section[0] + local_col
                if 0 <= pattern_col <= pattern_section[1]:
                    output[r][c] = grid[r][pattern_col]

    return output

